create index if not exists idx_patient_file_release_tenant on public.patient_portal_medical_file_releases(tenant_id);
create index if not exists idx_patient_file_release_released_by on public.patient_portal_medical_file_releases(released_by);
drop policy if exists patient_file_release_staff_write on public.patient_portal_medical_file_releases;
create policy patient_file_release_staff_insert on public.patient_portal_medical_file_releases for insert to authenticated with check (exists (select 1 from public.clinic_users cu where cu.tenant_id=patient_portal_medical_file_releases.tenant_id and cu.auth_user_id=(select auth.uid()) and cu.is_active=true and cu.deleted_at is null));
create policy patient_file_release_staff_update on public.patient_portal_medical_file_releases for update to authenticated using (exists (select 1 from public.clinic_users cu where cu.tenant_id=patient_portal_medical_file_releases.tenant_id and cu.auth_user_id=(select auth.uid()) and cu.is_active=true and cu.deleted_at is null)) with check (exists (select 1 from public.clinic_users cu where cu.tenant_id=patient_portal_medical_file_releases.tenant_id and cu.auth_user_id=(select auth.uid()) and cu.is_active=true and cu.deleted_at is null));
create policy patient_file_release_staff_delete on public.patient_portal_medical_file_releases for delete to authenticated using (exists (select 1 from public.clinic_users cu where cu.tenant_id=patient_portal_medical_file_releases.tenant_id and cu.auth_user_id=(select auth.uid()) and cu.is_active=true and cu.deleted_at is null));
